package com.payguard.payment.outbox; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface OutboxRepository extends JpaRepository<OutboxEntry,UUID>{ @Query(value="select * from outbox where published_at is null order by created_at for update skip locked limit :limit",nativeQuery=true) List<OutboxEntry> lockUnpublished(@Param("limit") int limit); }
